-- Backend Engineering ("The Fracture") Act 8 -- "Backend Codebase Design"
-- content. Closes Arc I ("Build"). 1 campaign, 2 operations, 12 missions.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be8', 'world-be-8', 'backend-codebase-design', '8A - Backend Codebase Design', 'Refactor a codebase with no boundaries into one with real ones, before the next incident makes the boundaries for you.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be8-1', 'campaign-be8', 'drawing-the-lines', 'Drawing the Lines', 'Layers, injection, inversion, clean and hexagonal architecture, and modules.', 1),
  ('operation-be8-2', 'campaign-be8', 'what-belongs-where', 'What Belongs Where', 'Domain models, application services, infrastructure, configuration and error boundaries -- then the refactor itself.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be8-01', 'world-be-8', 'campaign-be8', 'operation-be8-1', 'layered-architecture', 'Layered Architecture', 'Every incident this Arc traces back to a codebase with no boundaries. Drawing lines nothing is allowed to cross without going through a door is the fix.', 'intermediate', ARRAY['mira'], null, null, '{"type":"simulation","simulationId":"layer-sort-sim"}'::jsonb, '{"xp":150,"credits":25}'::jsonb, false, 1),
  ('mission-be8-02', 'world-be-8', 'campaign-be8', 'operation-be8-1', 'dependency-injection', 'Dependency Injection', 'A service that constructs its own database client inside itself can never be tested without a real one. Stop building your own dependencies -- accept them from outside.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be8-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"dependency-injection-sim"}'::jsonb, '{"xp":155,"credits":25}'::jsonb, false, 2),
  ('mission-be8-03', 'world-be-8', 'campaign-be8', 'operation-be8-1', 'dependency-inversion', 'Dependency Inversion', 'Injection is the mechanic. Inversion is the principle: high-level code should depend on an interface, never a concrete low-level detail.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be8-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"dependency-inversion-sim"}'::jsonb, '{"xp":155,"credits":25}'::jsonb, false, 3),
  ('mission-be8-04', 'world-be-8', 'campaign-be8', 'operation-be8-1', 'clean-architecture-concepts', 'Clean Architecture Concepts', 'Concentric circles: business rules in the center knowing nothing about the outside, frameworks and databases on the outer rings, dependencies always pointing inward.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be8-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"clean-architecture-sim"}'::jsonb, '{"xp":160,"credits":28}'::jsonb, false, 4),
  ('mission-be8-05', 'world-be-8', 'campaign-be8', 'operation-be8-1', 'hexagonal-architecture-concepts', 'Hexagonal Architecture Concepts', 'Ports and adapters: the same idea from a different angle. The core defines the ports it needs; adapters plug into them from the outside.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be8-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"hexagonal-architecture-sim"}'::jsonb, '{"xp":160,"credits":28}'::jsonb, false, 5),
  ('mission-be8-06', 'world-be-8', 'campaign-be8', 'operation-be8-1', 'modules', 'Modules', 'None of this works if a single file does everything. A module is a boundary with a clear public surface -- everything else is nobody else''s business.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be8-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"module-boundary-sim"}'::jsonb, '{"xp":165,"credits":28}'::jsonb, false, 6),
  ('mission-be8-07', 'world-be-8', 'campaign-be8', 'operation-be8-2', 'domain-models', 'Domain Models', 'A domain model isn''t a database row with extra steps. It''s the actual concept, carrying its own rules about which states are even valid.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be8-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"domain-model-sim"}'::jsonb, '{"xp":170,"credits":30}'::jsonb, false, 7),
  ('mission-be8-08', 'world-be-8', 'campaign-be8', 'operation-be8-2', 'application-services', 'Application Services', 'An application service orchestrates one specific use case, calling into domain models and infrastructure ports, holding no business rules of its own.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be8-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"application-service-sim"}'::jsonb, '{"xp":170,"credits":30}'::jsonb, false, 8),
  ('mission-be8-09', 'world-be-8', 'campaign-be8', 'operation-be8-2', 'infrastructure-layer', 'Infrastructure Layer', 'Everything that talks to the outside world on the application''s behalf. It should be swappable without touching a single business rule.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be8-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"infrastructure-layer-sim"}'::jsonb, '{"xp":175,"credits":30}'::jsonb, false, 9),
  ('mission-be8-10', 'world-be-8', 'campaign-be8', 'operation-be8-2', 'configuration-boundaries', 'Configuration Boundaries', 'Config has its own boundary problem: read it in one place, pass it explicitly to whoever needs it. Reaching for an env var deep inside business logic is the same mistake as hardcoding a database client.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be8-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"config-boundary-sim"}'::jsonb, '{"xp":180,"credits":32}'::jsonb, false, 10),
  ('mission-be8-11', 'world-be-8', 'campaign-be8', 'operation-be8-2', 'error-boundaries', 'Error Boundaries', 'The last boundary: what happens when something fails. Each layer catches what it can handle and translates what it can''t into something the next layer up actually understands.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be8-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"error-boundary-sim"}'::jsonb, '{"xp":185,"credits":32}'::jsonb, false, 11),
  ('mission-be8-12', 'world-be-8', 'campaign-be8', 'operation-be8-2', 'the-spaghetti-service', 'The Spaghetti Service', 'Every principle this Act taught, on one real service. Refactor it, and close out Arc I.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be8-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"spaghetti-service-boss-sim"}'::jsonb, '{"xp":430,"credits":90,"badgeIds":["spaghetti-service"],"skillXp":{"software_architecture":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be8-01', 1, 'mira', 'Every incident this Arc traces back to the same root cause, and it isn''t a missing test. It''s a codebase with no boundaries -- where a config change in one place breaks a validation rule in another nobody remembers writing.'),
  ('mission-be8-01', 2, 'mira', 'The fix isn''t more code. It''s drawing lines nothing is allowed to cross without going through a door. That''s what a layer actually is.'),
  ('mission-be8-02', 1, 'forge', 'A service that constructs its own database client inside itself can never be tested without a real database. Dependency injection just means: stop building your own dependencies, accept them from outside.'),
  ('mission-be8-03', 1, 'mira', 'Injection is the mechanic. Inversion is the principle behind it: high-level code should depend on an interface, not a concrete low-level detail. The direction of the dependency is what actually inverts.'),
  ('mission-be8-04', 1, 'forge', 'Clean Architecture draws the dependency-inversion idea as concentric circles: business rules in the center, knowing nothing about the outside; frameworks and databases on the outer rings, depending inward, never the reverse.'),
  ('mission-be8-05', 1, 'mira', 'Hexagonal architecture -- ports and adapters -- is the same idea from a different angle: the application core defines ports it needs, and adapters plug into them from the outside, whether that''s a REST controller or a test double.'),
  ('mission-be8-06', 1, 'forge', 'None of this works if a single file does everything. A module is a boundary with a clear public surface -- everything else inside it is nobody else''s business.'),
  ('mission-be8-07', 1, 'mira', 'A domain model isn''t a database row with extra steps. It''s the actual concept -- an Order, a Shipment -- carrying its own rules about what states are even valid.'),
  ('mission-be8-08', 1, 'forge', 'An application service orchestrates one specific use case -- place an order -- calling into domain models and infrastructure ports, but holding no business rules of its own.'),
  ('mission-be8-09', 1, 'mira', 'Infrastructure is everything that talks to the outside world on the application''s behalf -- the database driver, the payment SDK, the email sender. It should be swappable without touching a single business rule.'),
  ('mission-be8-10', 1, 'forge', 'Config -- env vars, feature flags, secrets -- has its own boundary problem: read it in one place, pass it explicitly to whoever needs it. Reaching for an environment variable deep inside business logic is the same mistake as hardcoding a database client.'),
  ('mission-be8-11', 1, 'mira', 'The last boundary: what happens when something fails. An error boundary means each layer catches what it can handle and translates what it can''t into something the next layer up actually understands.'),
  ('mission-be8-12', 1, 'mira', 'Every principle this Act taught, on one real service. Refactor it, and tell me what you find.'),
  ('mission-be8-12', 2, 'forge', 'Config leaking into business logic. Validation duplicated in three different files with three different rules. A database client constructed inside a domain model. Pick your battle.'),
  ('mission-be8-12', 3, 'forge', '...refactoring the routing table just surfaced something else. A route registered eight months ago, prefixed with a literal, uncommented "//" -- and nobody currently at Forge Division wrote it.'),
  ('mission-be8-12', 4, 'mira', 'That closes the loop on everything we''ve half-noticed all Arc. It''s not a bug. It''s not nothing, either. Filed, tracked -- and we move into data next, because whatever this is, it isn''t staying inside one service.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be8-01-o1', 'mission-be8-01', 1, 'Name the layers', 'Sort each responsibility into the layer it actually belongs to.'),
  ('mission-be8-02-o1', 'mission-be8-02', 1, 'Spot the injected dependency', 'Identify what makes this class''s dependency injectable instead of hardcoded.'),
  ('mission-be8-03-o1', 'mission-be8-03', 1, 'Explain the payoff', 'State what depending on an interface instead of a concrete class actually buys you.'),
  ('mission-be8-04-o1', 'mission-be8-04', 1, 'Order the rings', 'Order Clean Architecture''s circles from innermost to outermost.'),
  ('mission-be8-05-o1', 'mission-be8-05', 1, 'Trace the swap', 'Explain what has to change inside the core when an adapter is swapped.'),
  ('mission-be8-06-o1', 'mission-be8-06', 1, 'Judge the boundary', 'Sort each practice into a good or leaky module boundary.'),
  ('mission-be8-07-o1', 'mission-be8-07', 1, 'Place the rule', 'Identify which rule belongs inside the domain model itself.'),
  ('mission-be8-08-o1', 'mission-be8-08', 1, 'Sort the responsibilities', 'Assign each responsibility to domain, application service, or controller.'),
  ('mission-be8-09-o1', 'mission-be8-09', 1, 'Find the violation', 'Identify which evidence shows the infrastructure boundary has already been crossed.'),
  ('mission-be8-10-o1', 'mission-be8-10', 1, 'Find the leak', 'Identify the line that reads environment state directly inside business logic.'),
  ('mission-be8-11-o1', 'mission-be8-11', 1, 'Translate the failure', 'Decide what should actually cross the boundary when a low-level error occurs.'),
  ('mission-be8-12-o1', 'mission-be8-12', 1, 'Spot the config leak', 'Identify which boundary is violated by reading configuration directly inside business logic.'),
  ('mission-be8-12-o2', 'mission-be8-12', 2, 'Spot the duplication', 'Find the validation rule duplicated across all three layers.'),
  ('mission-be8-12-o3', 'mission-be8-12', 3, 'Spot the hardcoded dependency', 'Identify the line that hardcodes a concrete dependency instead of receiving it through injection.'),
  ('mission-be8-12-o4', 'mission-be8-12', 4, 'Close the refactor', 'State the one architectural principle that would have prevented all three violations at once.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be8-01-o1-c1', 'mission-be8-01-o1', 1, 'drag_and_drop', 'Sort each responsibility into the layer it actually belongs to.', '{"items":[{"id":"l1","text":"Handles the HTTP request, parses input, calls a service"},{"id":"l2","text":"Contains business rules and orchestrates the work"},{"id":"l3","text":"Talks to the database, external APIs, the filesystem"}],"targets":[{"id":"t1","label":"Presentation / controller layer"},{"id":"t2","label":"Application / service layer"},{"id":"t3","label":"Infrastructure layer"}]}'::jsonb, '{"correctMapping":{"l1":"t1","l2":"t2","l3":"t3"}}'::jsonb),

  ('mission-be8-02-o1-c1', 'mission-be8-02-o1', 1, 'code_debugging', 'Which line is what makes this class''s dependency injectable instead of hardcoded?', '{"language":"typescript","code":"class OrderService {\n  constructor(private db: DatabaseClient) {}\n\n  async createOrder(data: OrderInput) {\n    return this.db.insert(''orders'', data);\n  }\n}","question":"Which line is what makes this class''s dependency injectable instead of hardcoded?"}'::jsonb, '{"requiredLineIds":["  constructor(private db: DatabaseClient) {}"]}'::jsonb),

  ('mission-be8-03-o1-c1', 'mission-be8-03-o1', 1, 'multiple_choice', 'OrderService depends on a PaymentGateway interface, not the concrete StripeGateway class. What does this actually buy you?', '{"question":"OrderService depends on a PaymentGateway interface, not the concrete StripeGateway class. What does this actually buy you?","options":[{"id":"a","text":"Nothing, it''s just extra code"},{"id":"b","text":"The order logic can swap payment providers, or use a fake gateway in tests, without changing OrderService itself"},{"id":"c","text":"It makes the app run faster"},{"id":"d","text":"It''s required by TypeScript"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be8-04-o1-c1', 'mission-be8-04-o1', 1, 'interactive_diagram', 'Order Clean Architecture''s circles from innermost to outermost.', '{"diagramId":"clean-architecture-rings","hotspots":[{"id":"entities","label":"Entities / domain rules","explanation":"Business rules with zero knowledge of databases, frameworks, or HTTP."},{"id":"use_cases","label":"Application use cases","explanation":"Orchestrates entities to do something specific, still framework-agnostic."},{"id":"interface_adapters","label":"Interface adapters","explanation":"Controllers and presenters -- translate between use cases and the outside world."},{"id":"frameworks","label":"Frameworks & drivers","explanation":"The database, the web framework, the UI -- the most replaceable, outermost layer."}],"task":"Order Clean Architecture''s circles from innermost (most protected) to outermost."}'::jsonb, '{"correctOrderIds":["entities","use_cases","interface_adapters","frameworks"]}'::jsonb),

  ('mission-be8-05-o1-c1', 'mission-be8-05-o1', 1, 'multiple_choice', 'If you swap a Postgres adapter for a MongoDB adapter, what has to change inside the application core?', '{"question":"In hexagonal architecture, if you swap a Postgres adapter for a MongoDB adapter, what has to change inside the application core?","options":[{"id":"a","text":"Nothing -- the core only knows about the port (interface), not the adapter"},{"id":"b","text":"Every use case that touches data"},{"id":"c","text":"The port interface itself"},{"id":"d","text":"The whole application needs a rewrite"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-be8-06-o1-c1', 'mission-be8-06-o1', 1, 'drag_and_drop', 'Sort each practice into a good or leaky module boundary.', '{"items":[{"id":"m1","text":"Exports a single OrderService with typed methods"},{"id":"m2","text":"Other modules import OrderService''s internal database row type directly"},{"id":"m3","text":"Internal helper functions are not exported"},{"id":"m4","text":"A billing module reaches into the internal folder structure of the orders module"}],"targets":[{"id":"good","label":"Good boundary"},{"id":"leaky","label":"Leaky boundary"}]}'::jsonb, '{"correctMapping":{"m1":"good","m2":"leaky","m3":"good","m4":"leaky"}}'::jsonb),

  ('mission-be8-07-o1-c1', 'mission-be8-07-o1', 1, 'multiple_choice', 'Which of these belongs inside the Order domain model itself, not in a controller or a database row?', '{"question":"Which of these belongs inside the Order domain model itself, not in a controller or a database row?","options":[{"id":"a","text":"The HTTP status code returned to the client"},{"id":"b","text":"The rule that an order can''t be shipped before it''s paid"},{"id":"c","text":"The SQL table name the order is stored in"},{"id":"d","text":"The JSON field name used in the API response"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be8-08-o1-c1', 'mission-be8-08-o1', 1, 'drag_and_drop', 'Assign each responsibility to domain, application service, or controller.', '{"items":[{"id":"a1","text":"Validates that the order total matches its line items"},{"id":"a2","text":"Calls the payment gateway, then the order repository, in the right order"},{"id":"a3","text":"Decides the HTTP status code for the response"}],"targets":[{"id":"domain","label":"Domain model"},{"id":"application_service","label":"Application service"},{"id":"controller","label":"Controller"}]}'::jsonb, '{"correctMapping":{"a1":"domain","a2":"application_service","a3":"controller"}}'::jsonb),

  ('mission-be8-09-o1-c1', 'mission-be8-09-o1', 1, 'investigation', 'Which evidence shows the infrastructure boundary has already been violated?', '{"evidence":[{"id":"ev1","label":"Code review comment","detail":"OrderService imports PostgresClient directly and calls raw SQL inside its business logic method"},{"id":"ev2","label":"Test report","detail":"Unit tests for OrderService require a live database connection to run"},{"id":"ev3","label":"Architecture diagram","detail":"OrderRepository interface is defined in the domain layer; PostgresOrderRepository implements it in infrastructure"}],"question":"Which evidence shows the infrastructure boundary has already been violated?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be8-10-o1-c1', 'mission-be8-10-o1', 1, 'code_debugging', 'Which line breaks the configuration boundary by reading environment state directly inside business logic?', '{"language":"typescript","code":"function calculateShippingCost(order: Order) {\n  const rate = process.env.SHIPPING_RATE_PER_KG;\n  return order.weightKg * Number(rate);\n}","question":"Which line breaks the configuration boundary by reading environment state directly inside business logic?"}'::jsonb, '{"requiredLineIds":["  const rate = process.env.SHIPPING_RATE_PER_KG;"]}'::jsonb),

  ('mission-be8-11-o1-c1', 'mission-be8-11-o1', 1, 'multiple_choice', 'A database unique-constraint violation happens inside a repository. What should cross the boundary into the application service?', '{"question":"A database unique-constraint violation happens inside a repository. What should cross the boundary into the application service?","options":[{"id":"a","text":"The raw Postgres error object, unchanged"},{"id":"b","text":"A domain-meaningful error like DuplicateOrderError, translated at the boundary"},{"id":"c","text":"Nothing -- swallow the error silently"},{"id":"d","text":"A generic HTTP 500 thrown from inside the repository"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be8-12-o1-c1', 'mission-be8-12-o1', 1, 'multiple_choice', 'The spaghetti service''s OrderService reads process.env.TAX_RATE directly inside its calculateTotal() method, three layers deep. What boundary does this violate?', '{"question":"The spaghetti service''s OrderService reads process.env.TAX_RATE directly inside its calculateTotal() method, three layers deep in business logic. What boundary does this violate?","options":[{"id":"a","text":"Dependency inversion"},{"id":"b","text":"The configuration boundary"},{"id":"c","text":"The presentation layer"},{"id":"d","text":"Nothing, this is fine"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be8-12-o2-c1', 'mission-be8-12-o2', 1, 'investigation', 'Which validation rule is duplicated across all three layers, and should live in exactly one place?', '{"evidence":[{"id":"ev1","label":"OrderController","detail":"Validates order.total > 0 before calling the service"},{"id":"ev2","label":"OrderService","detail":"Also validates order.total > 0 before processing"},{"id":"ev3","label":"OrderRepository","detail":"Also validates order.total > 0 before the INSERT"}],"question":"Which pieces of evidence together show the same rule duplicated across all three layers?"}'::jsonb, '{"requiredEvidenceIds":["ev1","ev2","ev3"]}'::jsonb),
  ('mission-be8-12-o3-c1', 'mission-be8-12-o3', 1, 'code_debugging', 'Which line hardcodes a concrete dependency instead of receiving it through injection?', '{"language":"typescript","code":"class OrderRepository {\n  save(order: Order) {\n    const client = new PostgresClient(process.env.DATABASE_URL);\n    return client.query(''INSERT INTO orders VALUES ($1)'', [order]);\n  }\n}","question":"Which line hardcodes a concrete dependency instead of receiving it through injection?"}'::jsonb, '{"requiredLineIds":["    const client = new PostgresClient(process.env.DATABASE_URL);"]}'::jsonb),
  ('mission-be8-12-o4-c1', 'mission-be8-12-o4', 1, 'boss_encounter', 'Having found all three violations, state the one architectural principle that would have prevented them at once.', '{"stages":[{"objectiveRef":"mission-be8-12-o1","label":"The config leak"},{"objectiveRef":"mission-be8-12-o2","label":"The duplication"},{"objectiveRef":"mission-be8-12-o3","label":"The hardcoded dependency"}],"task":"Having found all three violations, state the one architectural principle that would have prevented them at once: each concern belongs in exactly one layer, and every other layer reaches it only through an explicit boundary."}'::jsonb, '{"requiredObjectiveIds":["mission-be8-12-o1","mission-be8-12-o2","mission-be8-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be8-01-o1-c1', 'orientation', 'Think about who''s closest to the outside world, and who''s closest to the disk.', 10, 1),
  ('mission-be8-01-o1-c1', 'solution', 'Controllers sit at the edge parsing input, services hold the actual rules, infrastructure does the I/O.', 20, 2),

  ('mission-be8-02-o1-c1', 'orientation', 'The class needs a database client to do its job -- the question is who decides which one.', 10, 1),
  ('mission-be8-02-o1-c1', 'solution', 'The constructor parameter is where the caller hands in the dependency, instead of the class building it itself.', 20, 2),

  ('mission-be8-03-o1-c1', 'orientation', 'Ask what changes, and what doesn''t, if you swap the concrete implementation out.', 10, 1),
  ('mission-be8-03-o1-c1', 'solution', 'OrderService never has to change -- only which concrete class gets wired in at startup does.', 20, 2),

  ('mission-be8-04-o1-c1', 'orientation', 'The center should be the part that would survive a framework rewrite untouched.', 10, 1),
  ('mission-be8-04-o1-c1', 'solution', 'Entities, then use cases, then interface adapters, then frameworks/drivers at the outer edge.', 20, 2),

  ('mission-be8-05-o1-c1', 'orientation', 'The core was never allowed to know which adapter it was talking to in the first place.', 10, 1),
  ('mission-be8-05-o1-c1', 'solution', 'Nothing -- that''s the entire point of depending on a port instead of a concrete implementation.', 20, 2),

  ('mission-be8-06-o1-c1', 'orientation', 'A boundary everyone can see through isn''t really a boundary.', 10, 1),
  ('mission-be8-06-o1-c1', 'solution', 'm1 and m3 keep internals private; m2 and m4 both reach past the public surface into internals.', 20, 2),

  ('mission-be8-07-o1-c1', 'orientation', 'Ask which of these would still be true even if you deleted the database and the API entirely.', 10, 1),
  ('mission-be8-07-o1-c1', 'solution', 'The payment-before-shipping rule is a business rule the domain model should enforce itself -- the others are delivery-mechanism details.', 20, 2),

  ('mission-be8-08-o1-c1', 'orientation', 'One of these owns a rule, one owns a sequence of steps, one owns the outside-world response format.', 10, 1),
  ('mission-be8-08-o1-c1', 'solution', 'a1 is a domain rule, a2 is exactly what an application service orchestrates, a3 belongs to the controller.', 20, 2),

  ('mission-be8-09-o1-c1', 'orientation', 'One of these describes the actual violation; the others are either a symptom or the correct pattern.', 10, 1),
  ('mission-be8-09-o1-c1', 'solution', 'ev1 -- business logic directly importing and calling the concrete Postgres client is the boundary violation; ev2 is just a consequence, and ev3 shows how it should look.', 20, 2),

  ('mission-be8-10-o1-c1', 'orientation', 'Business logic shouldn''t know config comes from environment variables at all -- it should just receive a value.', 10, 1),
  ('mission-be8-10-o1-c1', 'solution', 'Reading process.env directly inside the calculation function couples business logic to how configuration happens to be delivered.', 20, 2),

  ('mission-be8-11-o1-c1', 'orientation', 'The layer above shouldn''t need to know what database engine is even in use to handle this.', 10, 1),
  ('mission-be8-11-o1-c1', 'solution', 'Translate it into a domain-meaningful error at the boundary -- the caller shouldn''t need to know Postgres-specific error codes.', 20, 2),

  ('mission-be8-12-o1-c1', 'orientation', 'Ask where this configuration value should have been read, and who should have handed it down.', 10, 1),
  ('mission-be8-12-o1-c1', 'solution', 'Reading an environment variable three layers deep in business logic is exactly the configuration-boundary violation from earlier in this Act.', 20, 2),
  ('mission-be8-12-o2-c1', 'orientation', 'The same rule appearing three times isn''t defense in depth -- it''s three places that can now disagree.', 10, 1),
  ('mission-be8-12-o2-c1', 'solution', 'All three layers independently check order.total > 0 -- that rule belongs once, inside the Order domain model.', 20, 2),
  ('mission-be8-12-o3-c1', 'orientation', 'This is the exact same shape of mistake as the dependency-injection mission earlier in this Act.', 10, 1),
  ('mission-be8-12-o3-c1', 'solution', 'The repository constructs its own PostgresClient instead of receiving one through its constructor -- hardcoded, not injected.', 20, 2),
  ('mission-be8-12-o4-c1', 'orientation', 'Look at what all three violations had in common as a category of mistake, not as individual bugs.', 15, 1),
  ('mission-be8-12-o4-c1', 'solution', 'Every concern -- config, validation rules, concrete dependencies -- belongs in exactly one layer, reached by every other layer only through an explicit boundary, never by reaching in directly.', 25, 2);
